fn vec(items: Int, rest: Int) -> Vec<Int> {
    let mut v = vec()
    for _ in 0.range(items) {
        v.push(rest)
    }
    v
}

fn push(v: Vec<Int>, x: Int) -> Vec<Int> {
    let mut v2 = v
    v2.push(x)
    v2
}

fn len(v: Vec<Int>) -> Int {
    let mut count = 0
    for _ in v {
        count = count + 1
    }
    count
}

fn get(v: Vec<Int>, i: Int) -> Option<Int> {
    if len(v) <= i {
        None
    } else {
        Some(v.get(i).unwrap())
    }
}

fn range(a: Int, b: Int) -> Vec<Int> {
    let mut v = vec()
    for i in a.range(b) {
        v.push(i)
    }
    v
}

