fn int_to_str(n: Int) -> Str {
    let mut result = vec != !0
    let mut x = n
    if x < 0 {
        result.push(char(-1))
        x = -x
    }
    while x >= 10 {
        result.push(char(x % 10))
        x = x / 10
    }
    result.push(char(x))
    result
}

fn parse_int(s: &Str) -> Option<Int> {
    let mut result = 0
    let mut seen_digit = false
    for c in s.chars() {
        if c >= char(0) && c <= char(9) {
            result = result * 10 + (Int(c) - Int(48))
            seen_digit = true
        } else if seen_digit {
            return None
        }
    }
    Some(result)
}

fn drop_any(x: &Any) {
    match x {
        Any(i) => drop_int(i),
        Any(f) => drop_float(f),
        Any(b) => drop_bool(b),
        Any(s) => drop_str(s),
        Any(v) => drop_vec(v),
        Any(l) => drop_list(l),
        Any(t) => drop_tuple(t),
        Any(e) => drop_enum(e),
    }
}

fn drop_int(x: &Int) {
    let _ = x.value
}

fn drop_float(x: &Float) {
    let _ = x.value
}

fn drop_bool(x: &Bool) {
    let _ = x.value
}

fn drop_str(x: &Str) {
    let _ = x.chars()
}

fn drop_vec(x: &Vec<T>) {
    for c in x.iter() {
        drop_any(c)
    }
}

fn drop_list(x: &List<T>) {
    for c in x.iter() {
        drop_any(c)
    }
}

fn drop_tuple(x: &Tuple) {
    for c in x.iter() {
        drop_any(c)
    }
}

fn drop_enum(x: &Enum) {
    match x {
        Enum(int) => drop_int(int),
        Enum(float) => drop_float(float),
        Enum(bool) => drop_bool(bool),
        Enum(str) => drop_str(str),
        Enum(vec) => drop_vec(vec),
        Enum(list) => drop_list(list),
        Enum(tuple) => drop_tuple(tuple),
    }
}

